/**
 * Profile System
 *
 * Profiles control which workflow SKILL FILES are generated by `grspec update`.
 * They do NOT gate CLI command access — all CLI commands work regardless of profile.
 *
 * The practical effect: a workflow outside the user's profile won't have a skill file,
 * so AI assistants won't auto-discover it. But the user can always invoke the CLI
 * command directly (e.g., `grspec archive` works even without the archive skill installed).
 *
 * Tiers (cumulative):
 *   minimal  → base workflows only
 *   standard → minimal + execution discipline (DEFAULT)
 *   full     → standard + collaboration
 *   custom   → explicit list
 */

import type { Profile } from './global-config.js';
import { sanitizeWorkflowIds } from './retired-workflows.js';

export { RETIRED_WORKFLOW_IDS, sanitizeWorkflowIds } from './retired-workflows.js';

export const MINIMAL_WORKFLOWS = ['propose', 'explore', 'apply', 'sync', 'archive'] as const;

export const STANDARD_WORKFLOWS = [
  ...MINIMAL_WORKFLOWS,
  'tdd',
  'validate',
  'verify',
  'debug',
  'review',
  'wiki',
  'ui',
] as const;

export const FULL_WORKFLOWS = [
  ...STANDARD_WORKFLOWS,
  'new',
  'continue',
  'ff',
  'bulk-archive',
  'onboard',
  'parallel',
  'subagent',
] as const;

/** @deprecated Use MINIMAL_WORKFLOWS. Kept for backward compatibility. */
export const CORE_WORKFLOWS = MINIMAL_WORKFLOWS;

/**
 * All available workflows in the system.
 */
export const ALL_WORKFLOWS = [
  'propose',
  'explore',
  'new',
  'continue',
  'apply',
  'ff',
  'sync',
  'archive',
  'bulk-archive',
  'validate',
  'verify',
  'onboard',
  'tdd',
  'debug',
  'review',
  'parallel',
  'subagent',
  'wiki',
  'ui',
] as const;

export type WorkflowId = (typeof ALL_WORKFLOWS)[number];
export type CoreWorkflowId = (typeof CORE_WORKFLOWS)[number];

/**
 * Resolves which workflows should have skill files generated.
 * This determines AI assistant discoverability, not CLI command availability.
 *
 * - 'minimal' returns MINIMAL_WORKFLOWS
 * - 'standard' (default) returns STANDARD_WORKFLOWS
 * - 'full' returns FULL_WORKFLOWS
 * - 'custom' returns the provided customWorkflows, or empty array if not provided
 */
export function getProfileWorkflows(
  profile: Profile,
  customWorkflows?: string[]
): readonly string[] {
  switch (profile) {
    case 'minimal':
      return MINIMAL_WORKFLOWS;
    case 'full':
      return FULL_WORKFLOWS;
    case 'custom':
      return customWorkflows ? sanitizeWorkflowIds(customWorkflows) : [];
    case 'standard':
    default:
      return STANDARD_WORKFLOWS;
  }
}
